module fourteennm_ram_block
    (
	 clk0,
	 clk1,
	 aclr,
	 sclr,
	 ena0,
	 ena1,
	 
	 portaaddr,
	 portaaddr2,
	 portaaddrstall,
	 portaaddrstall2,
	 portabyteenamasks,
     portadatain,
     portare,	 
     portawe,
	 eccencbypass,
	 eccencparity,
	 
     portbaddr,
     portbaddr2,
     portbaddrstall,
     portbaddrstall2,
     portbbyteenamasks,
     portbdatain,
     portbre,
     portbwe,

	 portadataout,
	 
     portbdataout,
     eccstatus,
	 
     dftout,
     devclrn,	 
	 devpor
     );
// -------- GLOBAL PARAMETERS ---------
parameter clk0_input_clock_enable="none";
parameter clk1_input_clock_enable="none";
parameter clk0_output_clock_enable="none";
parameter clk1_output_clock_enable="none";
parameter enable_ecc = "false";
parameter ecc_pipeline_stage_enabled = "false";
parameter enable_ecc_encoder_bypass = "false";
parameter enable_force_to_zero = "false";
