module fourteennm_io_12_lane (
	//clocks and resets
	input  [1:0] phy_clk,
	input  [7:0] phy_clk_phs,
	input        reset_n,
	input        pll_locked,
	input        dll_ref_clk,
	output [5:0] ioereg_locked,

	//core interface
	input  [47:0] oe_from_core,
	input  [95:0] data_from_core,
	output [95:0] data_to_core,
	input  [15:0] mrnk_read_core,
	input  [15:0] mrnk_write_core,
	input   [3:0] rdata_en_full_core,
	output  [3:0] rdata_valid_core,

	//DBC interface
	input         core2dbc_rd_data_rdy,
	input         core2dbc_wr_data_vld0,
	input         core2dbc_wr_data_vld1,
	input  [12:0] core2dbc_wr_ecc_info,
	output        dbc2core_rd_data_vld0,
	output        dbc2core_rd_data_vld1,
	output	      dbc2core_rd_type,
	output [11:0] dbc2core_wb_pointer,
	output	      dbc2core_wr_data_rdy,

	//HMC interface
	input  [95:0] ac_hmc,
	output  [5:0] afi_rlat_core,
	output  [5:0] afi_wlat_core,
	input  [17:0] cfg_dbc,
	input  [50:0] ctl2dbc0,
	input  [50:0] ctl2dbc1,
	output [22:0] dbc2ctl,

	//Avalon interface
	input  [54:0] cal_avl_in,
	output [31:0] cal_avl_readdata_out,
	output [54:0] cal_avl_out,
	input  [31:0] cal_avl_readdata_in,

	//DQS interface
	input [1:0] dqs_in,
	input [1:0]	broadcast_in_bot,
	input [1:0]	broadcast_in_top,
	output [1:0] broadcast_out_bot,
	output [1:0] broadcast_out_top,

	//IO interface
	input  [11:0] data_in,
	output [11:0] data_out,
	output [11:0] data_oe,
	output [11:0] oct_enable,

	//DLL interface
	input   [2:0] core_dll,
	output [12:0] dll_core,

	//clock phase alignment daisy chain
	input	sync_clk_bot_in,
	output	sync_clk_bot_out,
	input	sync_clk_top_in,
	output	sync_clk_top_out,
	input	sync_data_bot_in,
	output	sync_data_bot_out,
	input	sync_data_top_in,
	output	sync_data_top_out,

    // Timing
    output [11:0] emif_phy_out_a,
    output [11:0] emif_phy_out_b,

	//DFT Outputs
	output [1:0]	dft_phy_clk,

	input   [99:0] dbg_in,
	output  [99:0] dbg_out

);

    //Parameters
parameter [7:0] pipe_latency = 8'd0;
parameter [6:0] dbc_wb_reserved_entry = 7'd0;
parameter [9:0] dll_ctl_static = 10'd0;
parameter [6:0] dqs_lgc_count_threshold = 7'd0;
parameter [5:0] db_afi_wlat_vlu = 6'd0;
parameter [5:0] db_afi_rlat_vlu = 6'd0;
parameter [9:0] dqs_lgc_pvt_input_delay_a = 10'd0;
parameter [9:0] dqs_lgc_pvt_input_delay_b = 10'd0;
parameter [12:0] pin_0_output_phase = 13'd0;
parameter [12:0] pin_1_output_phase = 13'd0;
parameter [12:0] pin_2_output_phase = 13'd0;
parameter [12:0] pin_3_output_phase = 13'd0;
parameter [12:0] pin_4_output_phase = 13'd0;
parameter [12:0] pin_5_output_phase = 13'd0;
parameter [12:0] pin_6_output_phase = 13'd0;
parameter [12:0] pin_7_output_phase = 13'd0;
parameter [12:0] pin_8_output_phase = 13'd0;
parameter [12:0] pin_9_output_phase = 13'd0;
parameter [12:0] pin_10_output_phase = 13'd0;
parameter [12:0] pin_11_output_phase = 13'd0;
parameter [12:0] dqs_lgc_phase_shift_b = 13'd0;
parameter [12:0] dqs_lgc_phase_shift_a = 13'd0;
