endmodule // fourteennm_sdm_vsblock

`timescale 1 ps/1 ps
module fourteennm_ff #(
   parameter power_up = "DONT_CARE",
   parameter is_wysiwyg = "false",
   parameter dont_touch = "false",
   parameter x_on_violation = "on",
   parameter bypassed = "false",
   parameter is_latch = "false",
   parameter lpm_type = "fourteennm_ff",
   parameter propagate_x = "off"
) (
   input d,
   input clk,
   input clrn,
   input aload,
   input sclr,
   input sclr1,
   input sload,
   input asdata,
   input ena,
   input devclrn,
   input devpor,
   output q
);

if (propagate_x == "off") begin
    fourteennm_ff_generic #(
        .power_up(power_up),
        .is_wysiwyg(is_wysiwyg),
        .dont_touch(dont_touch),
        .x_on_violation(x_on_violation),
        .bypassed(bypassed),
        .is_latch(is_latch),
        .lpm_type(lpm_type)
        ) fourteennm_ff_core (
            .d(d),
            .clk(clk),
            .clrn(clrn),
            .aload(aload),
            .sclr(sclr),
            .sclr1(sclr1),
            .sload(sload),
            .asdata(asdata),
            .ena(ena),
            .devclrn(devclrn),
            .devpor(devpor),
            .q(q)
        );
end else if (propagate_x == "on") begin
    fourteennm_ff_generic_x #(
        .power_up(power_up),
        .is_wysiwyg(is_wysiwyg),
        .dont_touch(dont_touch),
        .x_on_violation(x_on_violation),
        .bypassed(bypassed),
        .is_latch(is_latch),
        .lpm_type(lpm_type)
        ) fourteennm_ff_core (
            .d(d),
            .clk(clk),
            .clrn(clrn),
            .aload(aload),
            .sclr(sclr),
            .sclr1(sclr1),
            .sload(sload),
            .asdata(asdata),
            .ena(ena),
            .devclrn(devclrn),
            .devpor(devpor),
            .q(q)
        );
end
endmodule

