`timescale 1 ps / 1 ps
module fourteennm_dsp_prime
(
    // Input
    input tri0 clk,
    input tri0 [1:0] clr,
    input tri0 [87:0] cascade_weight_in,
    input tri0 [95:0] cascade_data_in,
    input tri0 [95:0] data_in,
    input tri0 [7:0] shared_exponent,
    input tri1 ena,
    input tri0 zero_en,
    input tri0 [1:0] feed_sel,
    input tri0 load_bb_one,
    input tri0 load_bb_two,
    input tri0 acc_en,
    input tri0 load_buf_sel,
    input tri0 mode_switch,
	
    // Outputs
    output [87:0] cascade_weight_out,
    output [95:0] cascade_data_out,
    output [36:0] result_h,
    output [37:0] result_l
);

    parameter powermode_dc = "powerdown";
    parameter dsp_ac_pwr_rules_en = "pwr_rules_disabled";
    parameter dsp_ac_pwr_toggle_rate = "high";
    parameter dsp_ac_pwr_uw_per_mhz = 20'd0;
    parameter dsp_operating_voltage = "standard";
    parameter dsp_partial_reconfig = "partial_reconfig_disabled";
    parameter dsp_clk_smux0_ce_ctrl = "clk_smux0_ce_enabled_with_leim_input";
    parameter dsp_clk_smux0_ctrl = "select_lsim4_for_clk_smux0";
    parameter dsp_clk_smux1_ctrl = "select_lsim4_for_clk_smux1";
    parameter dsp_clk_smux2_ctrl = "select_lsim4_for_clk_smux2";
    parameter dsp_nclr0_ctrl = "select_lsim10_for_nclr0";
    parameter dsp_nclr1_ctrl = "select_lsim11_for_nclr1";
    parameter dsp_dft = "dft_clk_disabled" ;
    parameter dsp_dft_for_op_clkce0_ctrl = "dft_itg_disabled" ;
    parameter dsp_dft_redmux = "dft_redmux_disabled";
    parameter dsp_dft_redmux_input = "dft_redmux_input_0";
    parameter dsp_dft_tdf = "dft_tdf_disabled";
    parameter dsp_fp32_sub_en = "float_sub_disabled";
    parameter dsp_mode = "tensor_fp";
    parameter dsp_sel_int4 = "select_int8";
    parameter dsp_cascade = "cascade_disabled";
    parameter dsp_pgm_invert_for_acc = "uninverted_acc_en";
    parameter dsp_pgm_invert_for_ce0 = "uninverted_ip_ce0";
    parameter dsp_pgm_invert_for_ce1 = "uninverted_ip_ce1";
    parameter dsp_pgm_invert_for_ce2 = "uninverted_ip_ce2";
    parameter dsp_pgm_invert_for_clk_smux0 = "select_uninverted_clk_smux0";
    parameter dsp_pgm_invert_for_clk_smux1 = "select_uninverted_clk_smux1";
    parameter dsp_pgm_invert_for_clk_smux2 = "select_uninverted_clk_smux2";
    parameter dsp_pgm_invert_for_feed_sel = "uninverted_feed_sel";
    parameter dsp_pgm_invert_for_load_bb_one = "uninverted_load_bb_one";
    parameter dsp_pgm_invert_for_load_bb_two = "uninverted_load_bb_two";
    parameter dsp_pgm_invert_for_load_buf_sel = "uninverted_load_buf_sel";
    parameter dsp_pgm_invert_for_nclr0 = "uninverted_nclr0";
    parameter dsp_pgm_invert_for_nclr1 = "uninverted_nclr1";
    parameter dsp_pgm_invert_for_zero = "uninverted_zero_en";
    parameter dsp_pgm_invert_for_switch_mode = "uninverted_switch_mode";
    parameter dsp_proginv_datain = 104'd0;
    parameter dsp_regscan_chain_enable = "disable_regscan_chain";
    parameter dsp_regscan_enable = "disable_regscan";

	fourteennm_dsp_prime_encrypted inst(
	// Input
	.clk(clk),
	.clr(clr),
	.cascade_weight_in(cascade_weight_in),
	.cascade_data_in(cascade_data_in),
	.data_in(data_in),
	.shared_exponent(shared_exponent),
	.ena(ena),
	.zero_en(zero_en),
	.feed_sel(feed_sel),
	.load_bb_one(load_bb_one),
	.load_bb_two(load_bb_two),
	.acc_en(acc_en),
	.load_buf_sel(load_buf_sel),
	.mode_switch(mode_switch),
	
	// Output
	.cascade_weight_out(cascade_weight_out),
	.cascade_data_out(cascade_data_out),
	.result_h(result_h),
	.result_l(result_l)
	);
	
	defparam inst.dsp_ac_pwr_rules_en = dsp_ac_pwr_rules_en;
	defparam inst.dsp_ac_pwr_toggle_rate=dsp_ac_pwr_toggle_rate;
	defparam inst.dsp_ac_pwr_uw_per_mhz = dsp_ac_pwr_uw_per_mhz;
	defparam inst.dsp_cascade = dsp_cascade;
	defparam inst.dsp_clk_smux0_ce_ctrl = dsp_clk_smux0_ce_ctrl;
	defparam inst.dsp_clk_smux0_ctrl = dsp_clk_smux0_ctrl;
	defparam inst.dsp_clk_smux1_ctrl = dsp_clk_smux1_ctrl;
	defparam inst.dsp_clk_smux2_ctrl = dsp_clk_smux2_ctrl;
	defparam inst.dsp_dft = dsp_dft;
	defparam inst.dsp_dft_for_op_clkce0_ctrl = dsp_dft_for_op_clkce0_ctrl;
	defparam inst.dsp_dft_redmux = dsp_dft_redmux;
	defparam inst.dsp_dft_redmux_input = dsp_dft_redmux_input;
	defparam inst.dsp_dft_tdf = dsp_dft_tdf;
	defparam inst.dsp_fp32_sub_en = dsp_fp32_sub_en;
	defparam inst.dsp_mode = dsp_mode;
	defparam inst.dsp_nclr0_ctrl = dsp_nclr0_ctrl;
	defparam inst.dsp_nclr1_ctrl = dsp_nclr1_ctrl;
	defparam inst.dsp_operating_voltage = dsp_operating_voltage;
	defparam inst.dsp_partial_reconfig = dsp_partial_reconfig;
	defparam inst.dsp_pgm_invert_for_acc = dsp_pgm_invert_for_acc;
	defparam inst.dsp_pgm_invert_for_ce0 = dsp_pgm_invert_for_ce0;
	defparam inst.dsp_pgm_invert_for_ce1 = dsp_pgm_invert_for_ce1;
	defparam inst.dsp_pgm_invert_for_ce2 = dsp_pgm_invert_for_ce2;
	defparam inst.dsp_pgm_invert_for_clk_smux0 = dsp_pgm_invert_for_clk_smux0;
	defparam inst.dsp_pgm_invert_for_clk_smux1 = dsp_pgm_invert_for_clk_smux1;
	defparam inst.dsp_pgm_invert_for_clk_smux2 = dsp_pgm_invert_for_clk_smux2;
//	defparam inst.dsp_pgm_invert_for_feed_sel = dsp_pgm_invert_for_feed_sel;
	defparam inst.dsp_pgm_invert_for_load_bb_one = dsp_pgm_invert_for_load_bb_one;
	defparam inst.dsp_pgm_invert_for_load_bb_two = dsp_pgm_invert_for_load_bb_two;
	defparam inst.dsp_pgm_invert_for_load_buf_sel = dsp_pgm_invert_for_load_buf_sel;	
	defparam inst.dsp_pgm_invert_for_nclr0 = dsp_pgm_invert_for_nclr0;
	defparam inst.dsp_pgm_invert_for_nclr1 = dsp_pgm_invert_for_nclr1;
	defparam inst.dsp_pgm_invert_for_zero = dsp_pgm_invert_for_zero;
	defparam inst.dsp_pgm_invert_for_switch_mode = dsp_pgm_invert_for_switch_mode;
	defparam inst.dsp_proginv_datain = dsp_proginv_datain;
	defparam inst.dsp_regscan_enable = dsp_regscan_enable;
	defparam inst.dsp_regscan_chain_enable = dsp_regscan_chain_enable;
	defparam inst.dsp_sel_int4 = dsp_sel_int4;
	defparam inst.powermode_dc = powermode_dc;
	
endmodule


